"use client";
import { type CSSProperties, type ReactNode, type RefObject } from "react";
import { sectionClamp } from "./section-math";
import {
  SectionImage,
  sectionStyles,
  useSectionEnvironment,
  useSectionScroll,
} from "./section-shared";
export interface StepWipeItem {
  id: string;
  title: string;
  description?: string;
  src?: string;
  alt?: string;
  content?: ReactNode;
  foreground?: { src: string; alt: string };
  color?: string;
}
export interface StepWipeProps {
  items: readonly StepWipeItem[];
  height?: number;
  scrollRange?: number;
  scrollContainer?: RefObject<HTMLElement | null>;
  onProgress?: (progress: number) => void;
  dim?: number;
  className?: string;
  style?: CSSProperties;
  label?: string;
}
/** Scroll-scrubbed product stages with distinct background and foreground wipe boundaries. */
export function StepWipe({
  items,
  height = 720,
  scrollRange = 2300,
  scrollContainer,
  onProgress,
  dim = 0.2,
  className = "",
  style,
  label = "Product stages",
}: StepWipeProps) {
  const env = useSectionEnvironment(),
    progress = useSectionScroll(env.ref, scrollContainer, onProgress),
    position = progress * Math.max(0, items.length - 1),
    active = Math.min(items.length - 1, Math.floor(position + 0.5));
  return (
    <div
      ref={env.ref}
      role="region"
      aria-label={label}
      tabIndex={0}
      className={`z-as z-as-step ${className}`}
      data-section="step-wipe"
      data-progress={progress.toFixed(4)}
      data-index={Math.max(0, active)}
      style={
        {
          height: `calc(min(${height}px,100svh) + ${Math.max(0, scrollRange)}px)`,
          "--section-height": `${height}px`,
          ...style,
        } as CSSProperties
      }
    >
      <style>
        {sectionStyles +
          `.z-as-step{color:white}.z-as-step .z-as-step-stage{position:absolute;inset:0}.z-as-step .z-as-step-title{position:absolute;top:28px;left:3.2%;right:3.2%;border-top:1px solid #fff5;padding-top:16px;font-size:clamp(32px,4vw,52px);font-weight:400;letter-spacing:-.035em}.z-as-step .z-as-step-frame{position:absolute;top:25%;left:26%;width:48%;height:50%;border-radius:12px;overflow:hidden}.z-as-step .z-as-step-copy{position:absolute;bottom:32px;left:3.2%;right:3.2%;display:flex;justify-content:space-between;gap:30px;align-items:flex-end}.z-as-step .z-as-step-copy strong{font-size:clamp(52px,7vw,90px);line-height:1;font-weight:400}.z-as-step .z-as-step-copy p{max-width:340px;font-size:14px;line-height:1.7}@media(max-width:600px){.z-as-step .z-as-step-frame{left:10%;width:80%;top:25%;height:39%}.z-as-step .z-as-step-copy p{max-width:65%;font-size:12px}.z-as-step .z-as-step-copy{bottom:25px}}`}
      </style>
      <div className="z-as-pin">
        {items.map((item, i) => {
          const reveal =
              i === 0 ? 1 : sectionClamp((position - (i - 1) - 0.15) / 0.7),
            amount = env.reduced ? (i <= active ? 1 : 0) : reveal,
            foreground = env.reduced
              ? amount
              : sectionClamp((position - (i - 1) - 0.27) / 0.62);
          return (
            <div
              key={item.id}
              className="z-as-step-stage"
              data-step-layer={i}
              aria-hidden={i !== active}
              style={{
                clipPath: `inset(${(1 - amount) * 100}% 0 0 0)`,
                background: item.color ?? "#444",
              }}
            >
              <SectionImage
                item={item}
                className="z-as-fill"
                style={{ transform: `scale(${1.07 - amount * 0.07})` }}
              />
              <div
                className="z-as-fill"
                style={{ background: `rgba(0,0,0,${dim})` }}
              />
              <h2 className="z-as-step-title">{item.title}</h2>
              <div
                className="z-as-step-frame"
                style={{ clipPath: `inset(0 0 ${(1 - foreground) * 100}% 0)` }}
              >
                <SectionImage item={item.foreground ?? item} />
              </div>
              <div className="z-as-step-copy">
                <span className="z-as-mask">
                  <strong
                    style={{
                      display: "block",
                      transform: `translateY(${(1 - foreground) * 110}%)`,
                    }}
                  >
                    {String(i + 1).padStart(2, "0")}
                  </strong>
                </span>
                <span className="z-as-mask">
                  <p
                    style={{
                      transform: `translateY(${(1 - foreground) * 110}%)`,
                    }}
                  >
                    {item.description}
                  </p>
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
